-- Contenus 12 : dhikr de la nuit (se retourner la nuit, frayeur dans le sommeil, rêve) (3 entrées).
-- Insérés NON validés (reviewed_at NULL) et NON affichés (enabled false) : rien n'apparaît chez les membres avant relecture
-- et validation dans Admin → Athkar. Idempotent : un dhikr déjà présent (même catégorie, même texte arabe) est ignoré.
-- Généré par ops/contenus/athkar/make_migration.py à partir de docs/contenus/athkar-*.json.

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ$q$, $q$La ilaha illa llahou l-wahidou l-qahharou, rabbou s-samawati wal-ardi wama baynahouma l-ʿazizou l-ghaffar$q$, $q$Il n’y a de divinité qu’Allah, l’Unique, le Dominateur suprême, Seigneur des cieux et de la terre et de ce qui est entre eux, le Puissant, le Grand Pardonneur. (à dire quand on se retourne d’un côté à l’autre pendant la nuit)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand on se retourne la nuit », invocation n° 1. Al-Hakim 1/540, jugé authentique, adh-Dhahabi d’accord ; an-Nasa’i, ‘Amal al-yawm wa-l-layla ; Ibn as-Sunni (voir Sahih al-Jami‘ 4/213).$q$, 1, 1000, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ$q$, $q$Aʿoudhou bikalimati llahi t-tammati min ghadabihi waʿiqabihi, wacharri ʿibadihi, wamin hamazati ch-chayatini wa’an yahdouroun$q$, $q$Je cherche refuge dans les paroles parfaites d’Allah contre Sa colère et Son châtiment, contre le mal de Ses serviteurs, contre les incitations des démons et contre le fait qu’ils soient présents auprès de moi. (en cas de frayeur ou d’angoisse dans le sommeil, ou d’isolement)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Frayeur et solitude dans le sommeil », invocation n° 1. Abu Dawud 4/12 (voir Sahih at-Tirmidhi 3/171).$q$, 1, 1001, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ وَمِنْ شَرِّ مَا رَأَيْتُ$q$, $q$Aʿoudhou billahi mina ch-chaytani wamin charri ma ra’ayt$q$, $q$Je cherche refuge auprès d’Allah contre Satan et contre le mal de ce que j’ai vu. (formule reconstituée : le recueil dit seulement que celui qui a vu un rêve qu’il n’aime pas crache légèrement à sa gauche, cherche refuge auprès d’Allah contre Satan et contre le mal de ce qu’il a vu, trois fois, n’en parle à personne et change de côté)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand on a vu un rêve », invocation n° 1. Muslim 4/1772-1773. ATTENTION : la source décrit l’action à la 3e personne (« il cherche refuge auprès d’Allah contre Satan et contre le mal de ce qu’il a vu ») sans donner de formule ; l’arabe ci-contre est une mise à la 1re personne faite par l’assistant, à valider.$q$, 1, 1002, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ وَمِنْ شَرِّ مَا رَأَيْتُ$q$);
